// Parse and normalize portfolio data from both API calls
const inputs = $input.all();

let activeCompanies = [];
let allCompanies = [];

for (const item of inputs) {
  const json = item.json;
  let companies = [];

  // Handle various response shapes
  if (json.companies && Array.isArray(json.companies)) {
    companies = json.companies;
  } else if (json.data && Array.isArray(json.data)) {
    companies = json.data;
  } else if (json.portfolio && Array.isArray(json.portfolio)) {
    companies = json.portfolio;
  } else if (json.results && Array.isArray(json.results)) {
    companies = json.results;
  } else if (Array.isArray(json)) {
    companies = json;
  }

  // Check which request this came from
  const queryStatus = json._request_query?.status || '';
  if (queryStatus === 'all' || companies.length === 0) {
    // This could be the 'all' request — use whichever has more
    if (companies.length >= activeCompanies.length) {
      allCompanies = companies;
    } else {
      allCompanies = companies.concat(activeCompanies);
    }
  } else {
    activeCompanies = companies;
    // Also save them into all
    if (allCompanies.length === 0) allCompanies = companies;
  }
}

// Deduplicate by id or name+url
const seen = new Set();
const dedupedAll = [...activeCompanies, ...allCompanies.filter(c => {
  const key = c.id || `${c.name}-${c.url || ''}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
})];

// Transform to standardized portfolio record format
const parsed = dedupedAll.map(company => ({
  portfolio_id: company.id || company.portfolio_id || company._id || '',
  name: company.name || company.business_name || company.company_name || company.title || 'Unknown',
  url: company.url || company.website || company.website_url || company.domain || '',
  status: company.status || company.portfolio_status || 'active',
  category: company.category || company.industry || company.niche || company.vertical || 'General',
  description: company.description 
    ? (company.description.substring(0, 500) + (company.description.length > 500 ? '...' : ''))
    : '',
  acquisition_date: company.acquisition_date || company.purchase_date || company.date_acquired || '',
  acquisition_price: company.acquisition_price || company.purchase_price || company.price || 0,
  current_valuation: company.current_valuation || company.valuation || company.estimated_value || 0,
  monthly_revenue: company.monthly_revenue || company.revenue || company.mrr || 0,
  monthly_profit: company.monthly_profit || company.profit || company.net_income || 0,
  platform: company.platform || company.tech_stack || company.built_on || '',
  tags: company.tags || company.features || company.labels || [],
  notes: company.notes || company.comments || '',
  logo_url: company.logo_url || company.logo || company.image_url || '',
  contact_email: company.contact_email || company.email || company.support_email || '',
  team_size: company.team_size || company.employees || company.headcount || 0,
  sync_source: 'multi-directory',
  last_synced: new Date().toISOString()
}));

return parsed;

// Calculate portfolio-wide statistics
const companies = $input.all().map(item => item.json);

const active = companies.filter(c => c.status === 'active');
const acquired = companies.filter(c => c.status === 'acquired' || c.status === 'sold');
const divested = companies.filter(c => c.status === 'divested' || c.status === 'sold');

const withRevenue = active.filter(c => c.monthly_revenue > 0);
const withProfit = active.filter(c => c.monthly_profit > 0);
const withAcqPrice = acquired.filter(c => c.acquisition_price > 0);
const withValuation = active.filter(c => c.current_valuation > 0);

const categoryBreakdown = companies.reduce((acc, c) => {
  const cat = c.category || 'Other';
  acc[cat] = (acc[cat] || 0) + 1;
  return acc;
}, {});

const statusBreakdown = companies.reduce((acc, c) => {
  acc[c.status] = (acc[c.status] || 0) + 1;
  return acc;
}, {});

const portfolioStats = {
  total_companies: companies.length,
  active_companies: active.length,
  acquired_companies: acquired.length,
  divested_companies: divested.length,
  total_monthly_revenue: withRevenue.reduce((s, c) => s + c.monthly_revenue, 0),
  avg_monthly_revenue: withRevenue.length > 0
    ? Math.round(withRevenue.reduce((s, c) => s + c.monthly_revenue, 0) / withRevenue.length)
    : 0,
  total_monthly_profit: withProfit.reduce((s, c) => s + c.monthly_profit, 0),
  total_acquisition_cost: withAcqPrice.reduce((s, c) => s + c.acquisition_price, 0),
  total_current_valuation: withValuation.reduce((s, c) => s + c.current_valuation, 0),
  total_invested: withAcqPrice.reduce((s, c) => s + c.acquisition_price, 0),
  roi_percentage: (() => {
    const invested = withAcqPrice.reduce((s, c) => s + c.acquisition_price, 0);
    const valued = withValuation.reduce((s, c) => s + c.current_valuation, 0);
    return invested > 0 ? Math.round(((valued - invested) / invested) * 100) : 0;
  })(),
  category_breakdown: categoryBreakdown,
  status_breakdown: statusBreakdown,
  sync_timestamp: new Date().toISOString(),
  source: 'multi-directory'
};

return {
  widget_key: 'portfolio_overview',
  widget_type: 'portfolio_sync',
  widget_label: 'Portfolio Companies Overview',
  source: 'multi-directory',
  summary: portfolioStats,
  companies: companies,
  user_id: $json.user_id || $json.body?.user_id || 'default',
  dashboard_type: 'portfolio',
  metadata: {
    sync_source: 'http://localhost:3001',
    sync_endpoint: '/api/v1/portfolio-companies',
    company_count: companies.length,
    active_count: active.length,
    sync_timestamp: new Date().toISOString()
  }
};

// Build individual company widgets for the dashboard
const payload = $input.first().json;
const companies = payload.companies || [];

// Split companies into batches to avoid payload size limits
const batchSize = 20;
const batches = [];
for (let i = 0; i < companies.length; i += batchSize) {
  batches.push(companies.slice(i, i + batchSize));
}

// Return each batch as a separate widget push
return batches.map((batch, idx) => ({
  widget_key: 'portfolio_companies',
  widget_type: 'portfolio_companies_list',
  widget_label: `Portfolio Companies (Batch ${idx + 1}/${batches.length})`,
  source: 'multi-directory',
  summary: {
    batch: idx + 1,
    total_batches: batches.length,
    companies_in_batch: batch.length,
    total_companies: companies.length
  },
  companies: batch,
  user_id: $json.user_id || payload.user_id || 'default',
  dashboard_type: 'portfolio',
  metadata: {
    batch_index: idx,
    batch_total: batches.length,
    sync_source: 'multi-directory',
    sync_timestamp: new Date().toISOString()
  }
}));
